#! /bin/bash

## TODO write this script in Clojure (to be run in the REPL)
## TODO make this script read the full name in comment of Lexer and assign it
##      in the parse-cases

GRAMMAR_DIR='env/dev/resources/grammars'

movements=$(grep "^[A-Z]" $GRAMMAR_DIR/MovementLexer.g4 \
              | cut -d ":" -f 1 \
              | grep -v -e WS -e SEP \
              | sort -u)

## Generate Parser ############################################################

PARSER_GRAMMAR_FILE="$GRAMMAR_DIR/MovementParser.g4"

cat << EOF > $PARSER_GRAMMAR_FILE
/* This file is generated by gen-movement-src.sh, don't edit! */

parser grammar MovementParser;

options { tokenVocab = MovementLexer; }

/*
 Parser Rules
 */

movement :
EOF

for m in ${movements[*]};
do
  echo "  | $m";
done >> $PARSER_GRAMMAR_FILE

echo '  ;' >> $PARSER_GRAMMAR_FILE


## Generate Clojure code ######################################################

CLJ_FILE='./src/clj/cfapp/api/domain/movement/parse_cases.clj'

toKeyword() {
  echo ":$1" | tr '[:upper:]' '[:lower:]' | tr '_' '-'
}

cat << EOF > $CLJ_FILE
;; This file is generated by gen-movement-src.sh, don't edit!
(ns cfapp.api.domain.movement.parse-cases)

(defn parse-cases
  [ctx]
  (cond
EOF

for m in ${movements[*]};
do
  echo -ne "\n    (.$m ctx) $(toKeyword $m)";
done >> $CLJ_FILE

echo '))' >> $CLJ_FILE
